+const form = document.getElementById('contactForm');
+const fullNameInput = document.getElementById('fullName');
+const emailInput = document.getElementById('email');
+const phoneInput = document.getElementById('phone');
+const successMessage = document.getElementById('successMessage');
+
+// Validation functions
+function validateFullName(value) {
+    const trimmed = value.trim();
+    if (trimmed === '') {
+        return { valid: false, message: 'Full name is required' };
+    }
+    if (trimmed.length < 2) {
+        return { valid: false, message: 'Full name must be at least 2 characters' };
+    }
+    return { valid: true, message: '' };
+}
+
+function validateEmail(value) {
+    const trimmed = value.trim();
+    if (trimmed === '') {
+        return { valid: false, message: 'Email address is required' };
+    }
+    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+    if (!emailRegex.test(trimmed)) {
+        return { valid: false, message: 'Please enter a valid email address' };
+    }
+    return { valid: true, message: '' };
+}
+
+function validatePhone(value) {
+    const trimmed = value.trim();
+    if (trimmed === '') {
+        return { valid: true, message: '' };
+    }
+    const phoneRegex = /^[\d\s\-()\.+]*$|^$/;
+    if (!phoneRegex.test(trimmed)) {
+        return { valid: false, message: 'Phone number contains invalid characters' };
+    }
+    const digitsOnly = trimmed.replace(/\D/g, '');
+    if (digitsOnly.length > 0 && (digitsOnly.length < 10 || digitsOnly.length > 15)) {
+        return { valid: false, message: 'Phone number must be between 10 and 15 digits' };
+    }
+    return { valid: true, message: '' };
+}
+
+function showValidationMessage(input, isValid, message) {
+    const errorElement = document.getElementById(input.id + 'Error');
+    
+    if (isValid) {
+        errorElement.textContent = '';
+        errorElement.classList.remove('show');
+        input.removeAttribute('aria-invalid');
+    } else {
+        errorElement.textContent = message;
+        errorElement.classList.add('show');
+        input.setAttribute('aria-invalid', 'true');
+    }
+}
+
+function validateField(input, validator) {
+    const result = validator(input.value);
+    showValidationMessage(input, result.valid, result.message);
+    return result.valid;
+}
+
+// Validate on blur
+fullNameInput.addEventListener('blur', () => {
+    validateField(fullNameInput, validateFullName);
+});
+
+emailInput.addEventListener('blur', () => {
+    validateField(emailInput, validateEmail);
+});
+
+phoneInput.addEventListener('blur', () => {
+    validateField(phoneInput, validatePhone);
+});
+
+// Validate on input (for better UX - clear error when user starts fixing)
+fullNameInput.addEventListener('input', () => {
+    if (fullNameInput.getAttribute('aria-invalid') === 'true') {
+        validateField(fullNameInput, validateFullName);
+    }
+});
+
+emailInput.addEventListener('input', () => {
+    if (emailInput.getAttribute('aria-invalid') === 'true') {
+        validateField(emailInput, validateEmail);
+    }
+});
+
+phoneInput.addEventListener('input', () => {
+    if (phoneInput.getAttribute('aria-invalid') === 'true') {
+        validateField(phoneInput, validatePhone);
+    }
+});
+
+// Handle form submission
+form.addEventListener('submit', (e) => {
+    e.preventDefault();
+
+    // Validate all fields
+    const fullNameValid = validateField(fullNameInput, validateFullName);
+    const emailValid = validateField(emailInput, validateEmail);
+    const phoneValid = validateField(phoneInput, validatePhone);
+
+    if (fullNameValid && emailValid && phoneValid) {
+        // Form is valid - show success message and reset form
+        successMessage.classList.add('show');
+        successMessage.setAttribute('aria-hidden', 'false');
+        form.reset();
+
+        // Clear aria-invalid attributes
+        fullNameInput.removeAttribute('aria-invalid');
+        emailInput.removeAttribute('aria-invalid');
+        phoneInput.removeAttribute('aria-invalid');
+
+        // Hide success message after 5 seconds
+        setTimeout(() => {
+            successMessage.classList.remove('show');
+            successMessage.setAttribute('aria-hidden', 'true');
+        }, 5000);
+
+        // Focus back to the first field for accessibility
+        fullNameInput.focus();
+    } else {
+        // Focus the first invalid field
+        if (!fullNameValid) {
+            fullNameInput.focus();
+        } else if (!emailValid) {
+            emailInput.focus();
+        } else if (!phoneValid) {
+            phoneInput.focus();
+        }
+    }
+});
